@Controller('dynamic-sequencer')
export class DynamicSequencerController {
  private readonly logger = new Logger(DynamicSequencerController.name);

  public constructor(private readonly dynamicSeqSer: DynamicSequencerService) {}

  @Get('getMesWk/:plant')
  @ApiOperation({
    summary: 'Get MES buffer data by plant for all MES-enabled workcenters',
  })
  @ApiParam({ description: 'ID of the plant', name: 'plantId', type: Number })
  @ApiQuery({
    description: 'Page number for pagination',
    example: 1,
    name: 'page',
    required: false,
    type: Number,
  })
  @ApiResponse({
    description: 'Paginated list of MES buffer records',
    schema: {
      properties: {
        data: {
          type: 'array',
        },
        limit: { type: 'number' },
        page: { type: 'number' },
        total: { type: 'number' },
      },
      type: 'object',
    },
    status: 200,
  })
  public async getMesWksByPlant(
    @Param('plant') plant: number,
    @Query('page') page: number,
  ): Promise<{
    data: Array<MesBufferDto>;
    total: number;
    page: number;
    limit: number;
  }> {
    try {
      return await this.dynamicSeqSer.getMesWksByPlant(plant, +page);
    } catch (error) {
      this.logger.error(
        `Failed to fetch MES workcenters for plant ${plant} (page ${page}): ${
          error.message ?? error
        }`,
      );

      // Return a safe fallback response
      return {
        data: [],
        limit: 0,
        page: +page,
        total: 0,
      };
    }
  }

  @Post('get-order-status/:plant')
  @ApiOperation({
    description:
      'Fetches production orders and their statuses for a given plant, supporting optional filters and pagination.',
    summary: 'Retrieve production order status from Order Management service',
  })
  @ApiParam({
    description: 'Plant identifier',
    example: 1146,
    name: 'plant',
    required: true,
    type: Number,
  })
  @ApiQuery({
    description: 'Page number for pagination',
    example: 1,
    name: 'page',
    required: false,
    type: Number,
  })
  @ApiBody({
    description: 'Optional filter criteria for production orders',

    examples: {
      default: {
        summary: 'Example filters',
        value: {
          materialNumber: [],
          orderId: ['PO-1234567890-TEST'],
          resource: ['RES-0001'],
          workcenter: ['WC-0001'],
        },
      },
    },
    required: false,
    type: GetOrderStatusRequestDto,
  })
  @ApiResponse({
    description: 'Successfully retrieved production order status data.',
    status: 200,
    type: GetOrderStatusResponseDto,
  })
  @ApiResponse({
    description: 'Invalid parameters or missing required fields.',
    status: 400,
  })
  @ApiResponse({
    description: 'Unexpected server error when fetching order status data.',
    status: 500,
  })
  public async getOrderStatus(
    @Param('plant', ParseIntPipe) plant: number,
    @Query('page', ParseIntPipe) page: number,
    @Body() filters: GetOrderStatusRequestDto,
  ): Promise<GetOrderStatusResponseDto> {
    if (!plant) {
      throw new BadRequestException('Plant parameter is required.');
    }

    return this.dynamicSeqSer.getOrderStatus(plant, filters, page);
  }
}

