import { Injectable, Logger } from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';
import { GetOrderStatusRequestDto } from './dto/get-order-status-request.dto';
import { GetOrderStatusResponseDto } from './dto/get-order-status-response.dto';
import { HttpHeadersDto } from './dto/header.dto';
import { MesBufferDto } from './dto/mes-buffer.dto';
import { MesWorkcenterDto } from './dto/mes-workcenter.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class DynamicSequencerService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(DynamicSequencerService.name);

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async findWksbyplantandworkcenter(
    plant: number,
    workcenters: MesWorkcenterDto,
    page: number,
  ): Promise<{
    data: Array<MesBufferDto>;
    total: number;
    page: number;
    limit: number;
  }> {
    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      const serviceAppId = this.daprConfigService.orderManagementApiAppId;
      const serviceMethod = `order-management/buffer/${plant}?page=${page}`;

      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.POST,
        workcenters,
        options,
      );

      if (!response) {
        throw new Error('Empty response from MES buffer service');
      }

      return response as {
        data: Array<MesBufferDto>;
        total: number;
        page: number;
        limit: number;
      };
    } catch (error) {
      this.logger.error(
        `Failed to fetch MES buffer for plant ${plant} (page ${page}): ${
          error.message ?? error
        }`,
      );
      throw new Error(
        `Error retrieving MES buffer data for plant ${plant}: ${
          error.message ?? 'Unknown error'
        }`,
      );
    }
  }

  public async getWorkcentersByPlant(plant: number): Promise<MesWorkcenterDto> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `workcenter/mes-workcenter/${plant}`;

    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };

      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
        undefined,
        options,
      );

      if (response) {
        return response as MesWorkcenterDto;
      }

      this.logger.warn(`Empty response received for plant ${plant}`);
      return { workcenters: [] };
    } catch (error) {
      this.logger.error(
        `Error while fetching workcenters for plant ${plant}: ${
          error.message ?? error
        }`,
      );

      return { workcenters: [] };
    }
  }

  public async getMesWksByPlant(
    plant: number,
    page: number,
  ): Promise<{
    data: Array<MesBufferDto>;
    total: number;
    page: number;
    limit: number;
  }> {
    const mesWorkcenters = await this.getWorkcentersByPlant(plant);

    const result = this.findWksbyplantandworkcenter(
      plant,
      mesWorkcenters,
      page,
    );
    return result;
  }

  public async getOrderStatus(
    plant: number,
    filters: GetOrderStatusRequestDto,
    page: number,
  ): Promise<GetOrderStatusResponseDto> {
    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const headersDto = new HttpHeadersDto();
      headersDto.authorization = `Bearer ${token}`;
      headersDto['Content-Type'] = 'application/json';
      const options = {
        headers: headersDto,
      };

      const serviceAppId = this.daprConfigService.orderManagementApiAppId;
      const serviceMethod = `order-management/production-order/get-order-status/${plant}?page=${page}`;

      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.POST,
        filters,
        options,
      );

      if (!response) {
        throw new Error('Empty response from production order service');
      }

      return response as GetOrderStatusResponseDto;
    } catch (error) {
      this.logger.error(
        `Failed to fetch order status for plant ${plant} (page ${page}): ${
          error.message ?? error
        }`,
      );
      throw new Error(
        `Error retrieving order status data for plant ${plant}: ${
          error.message ?? 'Unknown error'
        }`,
      );
    }
  }
}

